var e=[{patch:`11.7.8071`,version:`11.7`,name:`Summer Rewind`,date:`2024-07-09`,entry:{id:`thanatos`,name:`Thanatos`,verdict:`nerf`,quote:`Though Thanatos is always a pubstomping menace, it has become even more apparent how strong he is in the right hands with the TTK adjustments. Now that Health and Protections have gone down, his damage feels even more substantial, especially with his Death Scythe!`,groups:[{ability:`death_scythe`,name:`Death Scythe`,changes:[{stat:`Damage`,old:`100/170/240/310/380`,new:`95/165/235/305/375`},{stat:`Cooldown`,old:`12s at all ranks`,new:`14/13.5/13/12.5/12s`}]},{ability:`scent_of_death`,name:`Scent of Death`,changes:[{stat:`Penetration`,old:`10/15/20/25/30`,new:`5/10/15/20/25`}]}]}},{patch:`11.3.7948.6`,version:`11.3`,name:`Netherbeasts Bonus`,date:`2024-04-02`,entry:{id:`thanatos`,name:`Thanatos`,verdict:`nerf`,quote:`The Hand of Death is far and away still the most banned god in ranked by a significant margin, even despite receiving a couple recent nerfs. This is a very clear indication that players do not want to play against Thanatos, and as such, we are nerfing him again to bring his frustration factor down while still maintaining his identity.`,groups:[{ability:`scent_of_death`,name:`Scent of Death`,changes:[{stat:`Movement Speed and Bonus Movement Speed`,old:`10/15/20/25/30%`,new:`8/12/16/20/24%`}]},{ability:`hovering_death`,name:`Hovering Death`,changes:[{stat:`Cooldown`,old:`90s`,new:`110/105/100/95/90s`}]}]}},{patch:`11.2.7915.6`,version:`11.2`,name:`Goddess of the Sky Bonus`,date:`2024-03-05`,entry:{id:`thanatos`,name:`Thanatos`,verdict:`nerf`,quote:`The classic ranked menace, Thanatos, has maintained his status as a top ban for years. While this character has strong potential in the late game, it has always been his early game that stands out. We wanted to make sure his iconic Death Scythe damage still feels impactful, but by nudging the Penetration he gets from Scent of Death downward, it will strictly hone in on the high skill Thanatos players in the early game.`,groups:[{ability:`scent_of_death`,name:`Scent of Death`,changes:[{stat:`Penetration`,old:`15/20/25/30/35`,new:`10/15/20/25/30`}]}]}},{patch:`10.3.7494.12`,version:`10.3`,name:`Season of Hope`,date:`2023-03-28`,entry:{id:`thanatos`,name:`Thanatos`,verdict:`adjust`,quote:``,groups:[{name:`General`,changes:[{stat:`Health cost`,old:`abilities from 5%`,new:`4%`,note:`Ulti – 10% to 8%`}]},{ability:`harvester_of_souls`,name:`Harvester of Souls`,changes:[{stat:`HP Restore (Gods)`,old:`20% of target’s max HP`,new:`15%`},{stat:`HP Restore (Minions)`,old:`10% of target’s max HP`,new:`7%`}]},{ability:`death_scythe`,name:`Death Scythe`,changes:[{stat:`Cooldown`,old:`13s`,new:`12s`},{stat:`Healing`,old:`75% of damage dealt`,new:`50%`}]},{ability:`soul_reap`,name:`Soul Reap`,changes:[{stat:`Cooldown`,old:`15s`,new:`14s`}]},{ability:`hovering_death`,name:`Hovering Death`,changes:[{stat:`base Damage`,old:`from 90/125/160/195/230`,new:`110/145/180/215/250`},{stat:`Stun Duration`,old:`1s`,new:`1.5s`}]}]}},{patch:`3.20.3702.3`,version:`3.20`,name:`Cyber Sentinel`,date:`2016-10-25`,entry:{id:`thanatos`,name:`Thanatos`,verdict:`nerf`,quote:``,groups:[{name:`General`,changes:[{text:`Abilities now cost % of current Health, not % of total Health.`}]},{ability:`soul_reap`,name:`Soul Reap`,changes:[{stat:`Silence duration`,old:`.5/.75/1/1.25/1.5s`,new:`1s at all ranks`}]}]}},{patch:`3.11.3462`,version:`3.11`,name:`Expelled From Hel`,date:`2016-06-21`,entry:{id:`thanatos`,name:`Thanatos`,verdict:`buff`,quote:``,groups:[{ability:`soul_reap`,name:`Soul Reap`,changes:[{stat:`Scaling`,old:`60%`,new:`70%`}]}]}},{patch:`3.4.3299`,version:`3.4`,name:`Winter's Bite`,date:`2016-03-15`,entry:{id:`thanatos`,name:`Thanatos`,verdict:`buff`,quote:``,groups:[{name:`General`,changes:[{stat:`base physical protection`,old:`11`,new:`14`},{stat:`base attack power`,old:`37`,new:`39`}]}]}}];export{e as default};